Bytes ScriptSession::encodeDoodads(const jass::StableHandleMap& encodeHandle) const {
    constexpr size_t budget=64u*1024u*1024u;if(!runtime_.snapshotSafe() || failed_ || !world_ || !setupApplied_ || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty() || doodads_.size()>400000 || freeDoodads_.size()>doodads_.size())throw std::runtime_error("Doodad snapshot requires a quiescent local session");SnapshotWriter out(budget-64);out.u32(tag("SDOD"));out.u32(1);out.text(world_->resources().mapDigest(),64);out.u64(std::bit_cast<std::uint64_t>(simulationTime_));out.size(doodads_.size());std::set<std::uint32_t> stable;auto real=[&](float v){if(!std::isfinite(v))throw std::runtime_error("Invalid doodad value");out.u32(std::bit_cast<std::uint32_t>(v));};auto time=[&](double v){if(!std::isfinite(v))throw std::runtime_error("Invalid doodad time");out.u64(std::bit_cast<std::uint64_t>(v));};for(size_t i=0;i<doodads_.size();++i){auto& d=doodads_[i];out.u32(d.active?1:0);if(!d.active)continue;out.u32(d.type);auto saved=d.handle && encodeHandle?encodeHandle("destructable",d.handle):0;if(d.handle && (!saved || !stable.insert(saved).second || !alive(d.handle,NativeKind::Destructable) || !destructables_.contains(d.handle) || destructables_.at(d.handle)->doodadIndex!=i))throw std::runtime_error("Invalid doodad handle");out.u32(saved);real(d.x);real(d.y);out.text(d.animation,1024);out.text(d.randomAnimation,1024);time(d.animationStart);time(d.randomStart);out.u32(d.randomPhase);}out.size(freeDoodads_.size());std::vector<bool> freeSeen(doodads_.size());for(auto i:freeDoodads_){if(i>=doodads_.size() || doodads_[i].active || freeSeen[i])throw std::runtime_error("Invalid free doodad slot");freeSeen[i]=true;out.size(i);}for(size_t i=0;i<doodads_.size();++i)if(!doodads_[i].active && !freeSeen[i])throw std::runtime_error("Missing free doodad slot");out.size(doodadGrid_.size());std::vector<bool> gridSeen(doodads_.size());for(auto& [key,indices]:doodadGrid_){if(indices.empty())throw std::runtime_error("Invalid doodad grid");out.u32(std::bit_cast<std::uint32_t>(std::int32_t(key.first)));out.u32(std::bit_cast<std::uint32_t>(std::int32_t(key.second)));out.size(indices.size());for(auto i:indices){if(i>=doodads_.size() || !doodads_[i].active || gridSeen[i] || key!=std::pair{cell(doodads_[i].x),cell(doodads_[i].y)})throw std::runtime_error("Invalid doodad grid member");gridSeen[i]=true;out.size(i);}}for(size_t i=0;i<doodads_.size();++i)if(doodads_[i].active && !gridSeen[i])throw std::runtime_error("Missing doodad grid member");return sealSnapshot(out.finish(),budget);
}
void ScriptSession::restoreDoodads(std::span<const std::uint8_t> bytes,const jass::StableHandleMap& decodeHandle) {
    constexpr size_t budget=64u*1024u*1024u;if(!runtime_.ready() || failed_ || !world_ || !setupApplied_ || mainAttempted_ || doodadsRestored_ || !units_.empty() || runtime_.threadCount() || !runtime_.inspectExecutions().empty() || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty() || liveObjects(NativeKind::Event))throw std::runtime_error("Doodad restore requires rebuilt destructables before units");Binary in(openSnapshot(bytes,budget));in.expect(tag("SDOD"));if(in.u32()!=1 || snapshotText(in,64)!=world_->resources().mapDigest() || snapshotU64(in)!=std::bit_cast<std::uint64_t>(simulationTime_))throw std::runtime_error("Doodad map or clock differs");auto count=in.count(4,400000);std::vector<DoodadState> states;states.reserve(count);std::map<std::uint32_t,size_t> handles;auto real=[&]{auto v=std::bit_cast<float>(in.u32());if(!std::isfinite(v))throw std::runtime_error("Invalid doodad value");return v;};auto time=[&]{auto v=std::bit_cast<double>(snapshotU64(in));if(!std::isfinite(v))throw std::runtime_error("Invalid doodad time");return v;};for(unsigned i=0;i<count;++i){DoodadState d;auto active=in.u32();if(active>1)throw std::runtime_error("Invalid doodad flag");d.active=active!=0;if(d.active){d.type=in.u32();auto saved=in.u32();if(saved){d.handle=decodeHandle?decodeHandle("destructable",saved):0;if(!d.handle || !destructableIdentityHandles_.contains(saved) || destructableIdentityHandles_.at(saved)!=d.handle || !alive(d.handle,NativeKind::Destructable) || !destructables_.contains(d.handle) || !handles.emplace(d.handle,i).second)throw std::runtime_error("Invalid doodad handle");}d.x=real();d.y=real();d.animation=snapshotText(in,1024);d.randomAnimation=snapshotText(in,1024);d.animationStart=time();d.randomStart=time();d.randomPhase=in.u32();if(d.handle){auto& prop=*destructables_.at(d.handle);if(prop.type!=d.type || number(prop.position.x)!=d.x || number(prop.position.y)!=d.y)throw std::runtime_error("Doodad destructable differs");}}states.push_back(std::move(d));}if(handles.size()!=destructables_.size())throw std::runtime_error("Doodad destructable count differs");auto n=in.count(4,400000);std::vector<size_t> free;std::vector<bool> freeSeen(count);for(unsigned i=0;i<n;++i){auto index=in.u32();if(index>=count || states[index].active || freeSeen[index])throw std::runtime_error("Invalid free doodad slot");freeSeen[index]=true;free.push_back(index);}for(size_t i=0;i<count;++i)if(!states[i].active && !freeSeen[i])throw std::runtime_error("Missing free doodad slot");n=in.count(12,400000);std::map<std::pair<int,int>,std::vector<size_t>> grid;std::vector<bool> gridSeen(count);size_t gridCount=0;for(unsigned i=0;i<n;++i){auto x=in.i32(),y=in.i32();auto size=in.count(4,400000);if(!size || size>count-gridCount)throw std::runtime_error("Invalid doodad grid size");gridCount+=size;auto [it,inserted]=grid.emplace(std::pair{x,y},std::vector<size_t>{});if(!inserted)throw std::runtime_error("Duplicate doodad grid cell");for(unsigned j=0;j<size;++j){auto index=in.u32();if(index>=count || !states[index].active || gridSeen[index] || it->first!=std::pair{cell(states[index].x),cell(states[index].y)})throw std::runtime_error("Invalid doodad grid member");gridSeen[index]=true;it->second.push_back(index);}}for(size_t i=0;i<count;++i)if(states[i].active && !gridSeen[i])throw std::runtime_error("Missing doodad grid member");in.finish();doodads_.swap(states);freeDoodads_.swap(free);doodadGrid_.swap(grid);for(auto [id,index]:handles)destructables_.at(id)->doodadIndex=index;doodadsRestored_=true;
}
size_t ScriptSession::addDoodad(std::uint32_t type,float x,float y,std::uint32_t handle){
    if(!std::isfinite(x) || !std::isfinite(y))throw std::runtime_error("Non-finite doodad position");size_t index;
    if(freeDoodads_.empty()){if(doodads_.size()>=400000)throw std::runtime_error("Doodad count exceeds budget");index=doodads_.size();doodads_.emplace_back();}else{index=freeDoodads_.back();freeDoodads_.pop_back();doodads_[index]=DoodadState{};}
    auto& state=doodads_[index];state.type=type;state.handle=handle;state.x=x;state.y=y;doodadGrid_[{cell(x),cell(y)}].push_back(index);return index;
}
void ScriptSession::removeDoodad(size_t index){
    if(index>=doodads_.size() || !doodads_[index].active)return;auto& state=doodads_[index];auto bucket=doodadGrid_.find({cell(state.x),cell(state.y)});if(bucket!=doodadGrid_.end()){std::erase(bucket->second,index);if(bucket->second.empty())doodadGrid_.erase(bucket);}state=DoodadState{};state.active=false;freeDoodads_.push_back(index);
}
void ScriptSession::animateDoodads(const DoodadAnimation& command){
    double left=command.circular?double(command.x)-command.radius:number(command.rectangle.minX),right=command.circular?double(command.x)+command.radius:number(command.rectangle.maxX),bottom=command.circular?double(command.y)-command.radius:number(command.rectangle.minY),top=command.circular?double(command.y)+command.radius:number(command.rectangle.maxY);if(!std::isfinite(left) || !std::isfinite(right) || !std::isfinite(bottom) || !std::isfinite(top) || left>right || bottom>top)return;
    std::vector<size_t> matches;size_t nearest=SIZE_MAX;double nearestDistance=std::numeric_limits<double>::infinity();auto end=doodadGrid_.upper_bound({cell(right),INT_MAX});
    for(auto it=doodadGrid_.lower_bound({cell(left),INT_MIN});it!=end;++it){if(it->first.second<cell(bottom) || it->first.second>cell(top))continue;for(auto index:it->second){auto& d=doodads_[index];if(!d.active || (command.type && d.type!=command.type))continue;if(d.handle){auto found=destructables_.find(d.handle);if(found==destructables_.end() || found->second->removed)continue;}if(d.x<left || d.x>right || d.y<bottom || d.y>top)continue;double dx=double(d.x)-command.x,dy=double(d.y)-command.y,distance=dx*dx+dy*dy;if(command.circular && distance>double(command.radius)*command.radius)continue;if(command.nearest){if(distance<nearestDistance){nearestDistance=distance;nearest=index;}}else matches.push_back(index);}}
    if(nearest!=SIZE_MAX)matches.push_back(nearest);for(auto index:matches){auto& state=doodads_[index];state.randomStart=command.random?command.started:-1;state.randomAnimation=command.animation;state.randomPhase=std::uint32_t((index+1)*2654435761u)^state.type^std::uint32_t(std::uint64_t(command.started*1000));if(state.handle){auto found=destructables_.find(state.handle);if(found==destructables_.end() || found->second->removed)continue;auto& d=*found->second;d.animation=command.animation;d.resetAnimationClock(command.started);d.animationQueue.clear();animatedDestructables_.erase(state.handle);}else{state.animation=command.animation;state.animationStart=command.started;}}
}
